import{_ as l,a0 as d,w as s,s as a,I as r,x as e,a1 as n,A as i,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Windows 操作系統中運行 Docker 客户端 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Windows 操作系統中運行 Docker 客户端 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Windows 操作系統中運行 Docker 客户端 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Windows 操作系統中運行 Docker 客户端 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150512 How To Run Docker Client Inside Windows OS","title":"如何在 Windows 操作系統中運行 Docker 客户端","tag":"201506","desc":""},"relativePath":"201506/20150512 How To Run Docker Client Inside Windows OS.md","filePath":"[post].md"}'),k={name:"201506/20150512 How To Run Docker Client Inside Windows OS.md"};function c(u,o,w,D,h,g){const t=d("Link");return s(),a("div",null,[o[23]||(o[23]=r("h1",{id:"如何在-windows-操作系統中運行-docker-客户端",tabindex:"-1"},[e("如何在 Windows 操作系統中運行 Docker 客户端 "),r("a",{class:"header-anchor",href:"#如何在-windows-操作系統中運行-docker-客户端","aria-label":"Permalink to “如何在 Windows 操作系統中運行 Docker 客户端”"},"​")],-1)),r("p",null,[o[2]||(o[2]=e("大家好，今天我們來了解一下 Windows 操作系統中的 Docker 以及在其中安裝 Docker Windows 客户端的知識。Docker 引擎使用 Linux 特有的內核特性，因此不能通過 Windows 內核運行，所以，（在 Windows 上）Docker 引擎創建了一個小的虛擬系統運行 Linux 並利用它的資源和內核。這樣，Windows Docker 客户端就可以用這個虛擬的 Docker 引擎來構建、運行以及管理 Docker 容器。有個叫 Boot2Docker 的團隊開發了一個同名的應用程序，它創建了一個虛擬機來運行基於",-1)),n(t,{href:"http://tinycorelinux.net/"},{default:i(()=>[...o[0]||(o[0]=[e("Tiny Core Linux",-1)])]),_:1}),o[3]||(o[3]=e("特製的小型 Linux，來在 Windows 上運行 ",-1)),n(t,{href:"https://www.docker.io/"},{default:i(()=>[...o[1]||(o[1]=[e("Docker",-1)])]),_:1}),o[4]||(o[4]=e(" 容器。它完全運行在內存中，需要大約 27M 內存並能在 5秒 (因人而異) 內啓動。因此，在用於 Windows 的 Docker 引擎被開發出來之前，我們在 Windows 機器裏只能運行 Linux 容器。",-1))]),o[24]||(o[24]=r("p",null,"下面是安裝 Docker 客户端並在上面運行容器的簡單步驟。",-1)),o[25]||(o[25]=r("h3",{id:"_1-下載-boot2docker",tabindex:"-1"},[e("1. 下載 Boot2Docker "),r("a",{class:"header-anchor",href:"#_1-下載-boot2docker","aria-label":"Permalink to “1. 下載 Boot2Docker”"},"​")],-1)),r("p",null,[o[7]||(o[7]=e("在我們開始安裝之前，我們需要 Boot2Docker 的可執行文件。可以從 ",-1)),n(t,{href:"https://github.com/boot2docker/windows-installer/releases/latest"},{default:i(()=>[...o[5]||(o[5]=[e("它的 Github",-1)])]),_:1}),o[8]||(o[8]=e(" 下載最新版本的 Boot2Docker。在這篇指南中，我們從網站中下載版本 v1.6.1。我們從那網頁中用我們喜歡的瀏覽器或者下載管理器下載了名為 ",-1)),n(t,{href:"https://github.com/boot2docker/windows-installer/releases/download/v1.6.1/docker-install.exe"},{default:i(()=>[...o[6]||(o[6]=[e("docker-install.exe",-1)])]),_:1}),o[9]||(o[9]=e(" 的文件。",-1))]),o[26]||(o[26]=p(`<p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/downloading-boot2docker-installer.png" alt=""></p><h3 id="_2-安裝-boot2docker" tabindex="-1">2. 安裝 Boot2Docker <a class="header-anchor" href="#_2-安裝-boot2docker" aria-label="Permalink to “2. 安裝 Boot2Docker”">​</a></h3><p>現在我們運行安裝文件，它會安裝 Window Docker 客户端、用於 Windows 的 Git(MSYS-git)、VirtualBox、Boot2Docker Linux ISO 以及 Boot2Docker 管理工具，這些對於開箱即用地運行全功能的 Docker 引擎都至關重要。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/boot2docker-installer.png" alt=""></p><h3 id="_3-運行-boot2docker" tabindex="-1">3. 運行 Boot2Docker <a class="header-anchor" href="#_3-運行-boot2docker" aria-label="Permalink to “3. 運行 Boot2Docker”">​</a></h3><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/boot2docker-start-icon-e1431322598697.png" alt=""></p><p>安裝完成必要的組件之後，我們從桌面上的“Boot2Docker Start”快捷方式啓動 Boot2Docker。它會要求你輸入以後用於驗證的 SSH 密鑰。然後會啓動一個配置好的用於管理在虛擬機中運行的 Docker 的 unix shell。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/starting-boot2docker.png" alt=""></p><p>為了檢查是否正確配置，運行下面的 docker version 命令。</p><pre><code>docker version
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-version.png" alt=""></p><h3 id="_4-運行-docker" tabindex="-1">4. 運行 Docker <a class="header-anchor" href="#_4-運行-docker" aria-label="Permalink to “4. 運行 Docker”">​</a></h3><p>由於 <strong>Boot2Docker Start</strong> 自動啓動了一個已經正確設置好環境變量的 shell，我們可以馬上開始使用 Docker。<strong>請注意，如果我們要將 Boot2Docker 作為一個遠程 Docker 守護進程，那麼不要在 docker 命令之前加 sudo。</strong></p><p>現在，讓我們來試試 <strong>hello-world</strong> 例子鏡像，它會下載 hello-world 鏡像，運行並輸出 &quot;Hello from Docker&quot; 信息。</p><pre><code>$ docker run hello-world
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/running-hello-world.png" alt=""></p><h3 id="_5-使用命令提示符-cmd-運行-docker" tabindex="-1">5. 使用命令提示符(CMD) 運行 Docker### <a class="header-anchor" href="#_5-使用命令提示符-cmd-運行-docker" aria-label="Permalink to “5. 使用命令提示符(CMD) 運行 Docker###”">​</a></h3><p>現在，如果你想開始用命令提示符使用 Docker，你可以打開命令提示符(CMD.exe)。由於 Boot2Docker 要求 ssh.exe 在 PATH 中，我們需要在命令提示符中輸入以下命令使得 %PATH% 環境變量中包括 Git 安裝目錄下的 bin 文件夾。</p><pre><code>set PATH=%PATH%;&quot;c:\\Program Files (x86)\\Git\\bin&quot;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-in-cmd.png" alt=""></p><p>運行上面的命令之後，我們可以在命令提示符中運行 <strong>boot2docker start</strong> 啓動 Boot2Docker 虛擬機。</p><pre><code>boot2docker start
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-cmd-variables.png" alt=""></p><p><strong>注意</strong>: 如果你看到 machine does no exist 的錯誤信息，就運行 <strong>boot2docker init</strong> 命令。</p><p>然後複製上圖中控制台標出命令到 cmd.exe 中為控制台窗口設置環境變量，然後我們就可以像平常一樣運行 docker 容器了。</p><h3 id="_6-使用-powershell-運行-docker" tabindex="-1">6. 使用 PowerShell 運行 Docker <a class="header-anchor" href="#_6-使用-powershell-運行-docker" aria-label="Permalink to “6. 使用 PowerShell 運行 Docker”">​</a></h3><p>為了能在 PowerShell 中運行 Docker，我們需要啓動一個 PowerShell 窗口並添加 ssh.exe 到 PATH 變量。</p><pre><code>$Env:Path = &quot;\${Env:Path};c:\\Program Files (x86)\\Git\\bin&quot;
</code></pre><p>運行完上面的命令，我們還需要運行</p><pre><code>boot2docker start
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-in-powershell.png" alt=""></p><p>這會打印用於設置環境變量連接到虛擬機內部運行的 Docker 的 PowerShell 命令。我們只需要在 PowerShell 中運行這些命令就可以和平常一樣運行 docker 容器。</p><h3 id="_7-用-putty-登錄" tabindex="-1">7. 用 PUTTY 登錄 <a class="header-anchor" href="#_7-用-putty-登錄" aria-label="Permalink to “7.  用 PUTTY 登錄”">​</a></h3><p>Boot2Docker 會在%USERPROFILE%.ssh 目錄生成和使用用於登錄的公共和私有密鑰，我們也需要使用這個文件夾中的私有密鑰。私有密鑰需要轉換為 PuTTY 的格式。我們可以通過 puttygen.exe 實現。</p><p>我們需要打開 puttygen.exe 並從 %USERPROFILE%.ssh\\id_boot2docker 中導入(&quot;File&quot;-&gt;&quot;Load&quot; 菜單)私鑰，然後點擊 &quot;Save Private Key&quot;。然後用保存的文件通過 PuTTY 用 docker@127.0.0.1:2022 登錄。</p><h3 id="_8-boot2docker-選項" tabindex="-1">8. Boot2Docker 選項 <a class="header-anchor" href="#_8-boot2docker-選項" aria-label="Permalink to “8. Boot2Docker 選項”">​</a></h3><p>Boot2Docker 管理工具提供了一些命令，如下所示。</p><pre><code>$ boot2docker

Usage: boot2docker.exe [&lt;options&gt;] {help|init|up|ssh|save|down|poweroff|reset|restart|config|status|info|ip|shellinit|delete|download|upgrade|version} [&lt;args&gt;]
</code></pre><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>通過 Docker Windows 客户端使用 Docker 很有趣。Boot2Docker 管理工具是一個能使任何 Docker 容器能像在 Linux 主機上平滑運行的很棒的應用程序。如果你更仔細的話，你會發現 boot2docker 默認用户的用户名是 docker，密碼是 tcuser。最新版本的 boot2docker 設置了一個 host-only 的網絡適配器提供訪問容器的端口。一般來説是 192.168.59.103，但可以通過 VirtualBox 的 DHCP 實現改變。</p><p>如果你有任何問題、建議、反饋，請在下面的評論框中寫下來然後我們可以改進或者更新我們的內容。非常感謝！Enjoy:-)</p><hr>`,42)),r("p",null,[o[11]||(o[11]=e("via: ",-1)),n(t,{href:"http://linoxide.com/linux-how-to/run-docker-client-inside-windows-os/"},{default:i(()=>[...o[10]||(o[10]=[e("http://linoxide.com/linux-how-to/run-docker-client-inside-windows-os/",-1)])]),_:1})]),r("p",null,[o[15]||(o[15]=e("作者：",-1)),n(t,{href:"http://linoxide.com/author/arunp/"},{default:i(()=>[...o[12]||(o[12]=[e("Arun Pyasi",-1)])]),_:1}),o[16]||(o[16]=e(" 譯者：",-1)),n(t,{href:"https://github.com/ictlyh"},{default:i(()=>[...o[13]||(o[13]=[e("ictlyh",-1)])]),_:1}),o[17]||(o[17]=e(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:i(()=>[...o[14]||(o[14]=[e("wxy",-1)])]),_:1})]),r("p",null,[o[20]||(o[20]=e("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...o[18]||(o[18]=[e("LCTT",-1)])]),_:1}),o[21]||(o[21]=e(" 原創翻譯，",-1)),n(t,{href:"https://linux.cn/"},{default:i(()=>[...o[19]||(o[19]=[e("Linux中國",-1)])]),_:1}),o[22]||(o[22]=e(" 榮譽推出",-1))])])}const f=l(k,[["render",c]]);export{x as __pageData,f as default};
